### Paso 3: JavaScript — interactividad

```js
// script.js

// --- Alternar modo oscuro ---
let botonContacto = document.querySelector("#btn-contacto");

botonContacto.addEventListener("click", function() {
    let cuerpo = document.querySelector("body");
    let fondoActual = cuerpo.style.backgroundColor;

    if (fondoActual === "" || fondoActual === "#f4f4f4") {
        cuerpo.style.backgroundColor = "#1a1a2e";
        cuerpo.style.color = "#eee";
        botonContacto.textContent = "Modo claro";
    } else {
        cuerpo.style.backgroundColor = "#f4f4f4";
        cuerpo.style.color = "#333";
        botonContacto.textContent = "Modo oscuro";
    }
});

// --- Animación al hacer scroll ---
let proyectos = document.querySelectorAll(".proyecto");

function revisarVisibilidad() {
    proyectos.forEach(function(proyecto) {
        let rect = proyecto.getBoundingClientRect();
        if (rect.top < window.innerHeight - 100) {
            proyecto.style.opacity = "1";
            proyecto.style.transform = "translateY(0)";
        }
    });
}

// Inicializar proyectos invisibles
proyectos.forEach(function(proyecto) {
    proyecto.style.opacity = "0";
    proyecto.style.transform = "translateY(30px)";
    proyecto.style.transition = "opacity 0.6s, transform 0.6s";
});

// Escuchar scroll
window.addEventListener("scroll", revisarVisibilidad);
revisarVisibilidad(); // ejecutar al cargar
```

### Explicación del JavaScript

1. **Modo oscuro:** cuando el usuario hace clic en el botón de contacto, cambia el fondo de toda la página. Usamos `body.style.backgroundColor` para leer y modificar el estilo. Un `if`/`else` alterna entre modo claro y oscuro, y cambia el texto del botón.

2. **Animación al hacer scroll:** seleccionamos todos los `.proyecto`. Al inicio, los ponemos invisibles (`opacity: 0`) y desplazados hacia abajo (`translateY(30px)`). La función `revisarVisibilidad` calcula si cada proyecto está visible en la pantalla usando `getBoundingClientRect()`. Si lo está, lo animamos a opacidad completa y posición original.

